                 const d=crel('circle',{cx:'50',cy:t.y,r:'3',fill:t.col});d.setAttribute('filter','url(#cr-glow-gold)');
                 document.getElementById('cr-lyr-players').appendChild(d);
                 animLine('cr-lyr-conn',50,t.y,18,t.y,t.col,.8,.0,null,false);
                 document.getElementById('cr-lyr-labels').appendChild(ctxt(14,t.y,t.yr,'2.8',t.col,'900','end'));
